        logits = self.router(x).float()                                   # (B,T,E)
        probs = logits.softmax(-1)
        top_p, top_i = probs.topk(K, dim=-1)                              # (B,T,K)
        gate = top_p / top_p.sum(-1, keepdim=True) if K > 1 else top_p
        onehot = F.one_hot(top_i, E)                                      # (B,T,K,E)
        assign = onehot.sum(2)                                            # (B,T,E) in {0,1}
        before = assign.cumsum(1) - assign                                # earlier same-row tokens per expert
        rank = (before.unsqueeze(2) * onehot).sum(-1)                     # (B,T,K)
        C = min(self.capacity, T)
        keep = rank < C
        rows = torch.arange(B, device=x.device).view(B, 1, 1)
        dump = E * B * C
        slot = torch.where(keep, (top_i * B + rows) * C + rank, torch.full_like(rank, dump))  # (B,T,K)
        tokens = torch.arange(B * T, device=x.device).view(B, T, 1).expand(B, T, K)
        source = torch.full((dump + 1,), B * T, dtype=torch.long, device=x.device)
        source = source.scatter(0, slot.reshape(-1), tokens.reshape(-1))[:dump]
        padded = torch.cat((x.reshape(B * T, D), x.new_zeros(1, D)), 0)
        xin = padded.index_select(0, source).view(E, B * C, D)
        outs = [self.w_out[e](F.relu(self.w_in[e](xin[e])).square()) for e in range(E)]
        yout = torch.cat(outs + [x.new_zeros(1, D)], 0)                   # (E*B*C+1, D)
        picked = yout.index_select(0, slot.reshape(-1)).view(B, T, K, D)
        weight = (gate * keep).to(x.dtype)
        routed = (picked * weight.unsqueeze(-1)).sum(2)
        y = y + routed
        if self.training and self.aux_weight > 0:
            frac = assign.float().mean((0, 1)) / K                        # fraction of choices per expert
            mean_p = probs.mean((0, 1))
            self.last_aux = self.aux_weight * E * (frac.detach() * mean_p).sum()
        else:
            self.last_aux = None
        return y


def make_ffn(config, layer):
    if config.option("moe_experts") > 0:
        return MoEFFN(config, layer)
    return CanonMLP(config)


@torch.no_grad()
def init_ffn(model):
    s = 3 ** 0.5 * model.config.width ** -0.5
    for block in model.transformer.h:
        mlp = block.mlp
        if isinstance(mlp, MoEFFN):
            for w in mlp.w_in:
                nn.init.uniform_(w.weight, -s * 0.4, s * 0.4)
            for w in mlp.w_out:
                nn.init.zeros_(w.weight)
            nn.init.normal_(mlp.router.weight, std=float(model.config.option("router_init")))


class ProbeMLP(CanonMLP):
    """Dense MLP plus one probed operator whose result joins the output with weight zero."""

    def __init__(self, config):
        super().__init__(config)
        self.probe = config.option("probe")
        self.router = Linear(config.width, 8, bias=False)

    def forward(self, x):
        y = super().forward(x)
        B, T, D = x.shape
        p = self.probe
        logits = self.router(x).float()
        z = None
        if p == "softmax":
            z = logits.softmax(-1).sum()
        elif p == "topk":
            v, i = logits.topk(2, dim=-1); z = v.sum()
        elif p == "topk_idx":
            v, i = logits.topk(2, dim=-1); z = v.sum() + i.float().sum()
        elif p == "argmax":
            i = logits.argmax(-1); z = i.float().sum() + logits.sum()
        elif p == "onehot":
            i = logits.argmax(-1); z = F.one_hot(i, 8).float().sum() + logits.sum()
        elif p == "eq_onehot":
            i = logits.argmax(-1); oh = (i.unsqueeze(-1) == torch.arange(8, device=x.device)); z = oh.float().sum() + logits.sum()
        elif p == "cumsum_f":
            z = logits.cumsum(1).sum()
        elif p == "cumsum_i":
            i = logits.argmax(-1); z = i.cumsum(1).float().sum() + logits.sum()
        elif p == "scatter_i":
            i = logits.argmax(-1).reshape(-1)
            s = torch.zeros(B * T, dtype=torch.long, device=x.device).scatter(0, i, torch.arange(B * T, device=x.device))
            z = s.float().sum() + logits.sum()
        elif p == "index_select":
            i = logits.argmax(-1).reshape(-1)
            z = x.reshape(B * T, D).index_select(0, i).sum()
        elif p == "getitem_idx":
            i = logits.argmax(-1).reshape(-1)
            z = x.reshape(B * T, D)[i].sum()
        elif p == "gather":
            i = logits.argmax(-1, keepdim=True)
            z = logits.gather(-1, i).sum()
        elif p == "cat":
            z = torch.cat((x.reshape(B * T, D), x.new_zeros(1, D)), 0).sum()
        elif p == "where":
            z = torch.where(logits > 0, logits, torch.zeros_like(logits)).sum()
        elif p == "sort":
            v, i = logits.sort(-1); z = v.sum()
        elif p == "argsort":
            i = logits.argsort(1); z = i.float().sum() + logits.sum()
        elif p == "index_add":
            i = logits.argmax(-1).reshape(-1)
            z = x.new_zeros(B * T, D).index_add(0, i, x.reshape(B * T, D)).sum()
        elif p == "scatter_add":
            i = logits.argmax(-1).reshape(-1, 1).expand(B * T, D)
            z = x.new_zeros(B * T, D).scatter_add(0, i, x.reshape(B * T, D)).sum()
        elif p == "bmm":
            z = torch.bmm(x.reshape(B, T, D), x.reshape(B, T, D).transpose(1, 2)).sum()
        elif p == "arange_mul":
            z = (logits * torch.arange(8, device=x.device)).sum()
        elif p == "full_like":
            z = (logits + torch.full_like(logits, 2.0)).sum()
        elif p == "lt":
            z = (logits < 0.5).float().sum() + logits.sum()
        elif p == "mul_int":
            i = logits.argmax(-1); z = (i * 3 + 1).float().sum() + logits.sum()
        elif p == "embedding":
            i = logits.argmax(-1); z = F.embedding(i, self.router.weight).sum()
        elif p == "sigmoid":
            z = logits.sigmoid().sum()
        elif p == "clamp":
            z = logits.clamp(max=1.0).sum()
        elif p == "remainder":
            i = logits.argmax(-1); z = (i % 3).float().sum() + logits.sum()
        elif p == "bitwise":
            i = logits.argmax(-1); z = (i ^ 5).float().sum() + logits.sum()
        elif p == "logsumexp":
            z = logits.logsumexp(-1).sum()
        elif p == "max":
            z = logits.amax(-1).sum()
        if z is None:
            raise ValueError("unknown probe")
        return y + 0.0 * z.to(y.dtype)


def make_ffn(config, layer):
    return ProbeMLP(config)

