        elif p == "cumsum_f":
            z = logits.cumsum(1).sum()
        elif p == "cumsum_i":
            i = logits.argmax(-1); z = i.cumsum(1).float().sum() + logits.sum()
        elif p == "scatter_i":
            i = logits.argmax(-1).reshape(-1)
            s = torch.zeros(B * T, dtype=torch.long, device=x.device).scatter(0, i, torch.arange(B * T, device=x.device))
            z = s.float().sum() + logits.sum()
        elif p == "index_select":
            i = logits.argmax(-1).reshape(-1)
            z = x.reshape(B * T, D).index_select(0, i).sum()
        elif p == "getitem_idx":
            i = logits.argmax(-1).reshape(-1)
